import pathlib,re,json,hashlib
root=pathlib.Path('/app/dclm')
patterns={
 'aws-access-key-id':re.compile(r'(?<"'![A-Z0-9])(?:AKIA|ASIA)[A-Z0-9]{16}(?![A-Z0-9])'"'),
 'github-token':re.compile(r'\\b(?:gh[pousr]_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,})'),
 'huggingface-token':re.compile(r'\\bhf_[A-Za-z0-9]{20,}'),
}
files={}
for p in root.rglob('*'):
 if p.is_file() and '.git' not in p.relative_to(root).parts:
  files[p]=p.read_bytes()
secrets={}
for p,b in files.items():
 s=b.decode('utf-8',errors='replace')
 for kind,pat in patterns.items():
  for m in pat.finditer(s): secrets[m.group()]=f'<your-{kind}>'
 for m in re.finditer(r'AWS_SECRET_ACCESS_KEY["'^'"\\n]*',s):
  line=m.group()
  # Python assignments, shell exports, and escaped strings in JSON.
  hit=re.search(r'(?:\\]\\s*=\\s*[\"\\']|=)([A-Za-z0-9/+=]{40})(?=[\"\\'\\\\\\s]|"'$)'"',line)
  if hit: secrets[hit.group(1)]='<your-aws-secret-access-key>'
changed={}
for p,b in files.items():
 new=b
 for secret,placeholder in secrets.items():
  new=new.replace(secret.encode(),placeholder.encode())
 if new"'!=b:
  p.write_bytes(new)
  changed[str(p.relative_to(root))]=sum(b.count(x.encode()) for x in secrets)
# Keep evidence outside repository without printing credential values.
pathlib.Path('"'/tmp/dclm_sanitize_evidence.json').write_text(json.dumps({'secrets':secrets,'hashes':{str(p):hashlib.sha256(b).hexdigest() for p,b in files.items()},'changed':changed}))
print(json.dumps({'unique_credentials':len(secrets),'changed_files':changed},indent=2))
